SELECT CNTNTS_ID, CNTNTS_NM, CNTC_URL, CNTNTS_USE_AT, CNTNTS_LINK_URL, CNTNTS_DC FROM COMTNINDVDLPGECNTNTS WHERE 1=1 AND ROWNUM > #{firstIndex} AND ROWNUM <= #{firstIndex} + #{recordCountPerPage}
AND CNTNTS_NM LIKE '%'||#{searchKeyword}||'%'
ORDER BY CNTNTS_ID DESC


SELECT CNTNTS_ID, CNTNTS_NM, CNTC_URL, CNTNTS_USE_AT, CNTNTS_LINK_URL, CNTNTS_DC 
FROM COMTNINDVDLPGECNTNTS
WHERE 1 = 1 AND CNTNTS_ID=#{cntntsId}

